use faucet_common_pubsub::PubsubMessage;
use faucet_core::Source;
use faucet_source_pubsub::{PubsubConnection, PubsubCredentials, PubsubSourceConfig, ValueFormat};
use gcloud_pubsub::client::{Client, ClientConfig};
use serde_json::json;

fn emulator_host() -> Option<String> {
    std::env::var("PUBSUB_EMULATOR_HOST").ok().filter(|h| !h.is_empty())
}

async fn emulator_client() -> Client {
    // ClientConfig::default() reads PUBSUB_EMULATOR_HOST + PUBSUB_PROJECT_ID.
    let config = ClientConfig::default();
    Client::new(config).await.expect("emulator client")
}

async fn setup(client: &Client, topic_id: &str, sub_id: &str) {
    let topic = client.create_topic(topic_id, None, None).await.expect("create topic");
    let _ = client
        .create_subscription(sub_id, topic.fully_qualified_name(), Default::default(), None)
        .await
        .expect("create subscription");
}

async fn publish(client: &Client, topic_id: &str, payloads: &[serde_json::Value]) {
    let topic = client.topic(topic_id);
    let publisher = topic.new_publisher(None);
    for p in payloads {
        let msg = PubsubMessage {
            data: serde_json::to_vec(p).unwrap(),
            ..Default::default()
        };
        let awaiter = publisher.publish(msg).await;
        awaiter.get().await.expect("publish");
    }
}

#[tokio::test]
async fn source_pulls_and_acks_published_messages() {
    let Some(_host) = emulator_host() else {
        eprintln!("skipping: PUBSUB_EMULATOR_HOST not set");
        return;
    };
    let project = std::env::var("PUBSUB_PROJECT_ID").unwrap_or_else(|_| "faucet-test".into());
    let topic_id = "faucet-it-topic";
    let sub_id = "faucet-it-sub";

    let client = emulator_client().await;
    setup(&client, topic_id, sub_id).await;
    publish(
        &client,
        topic_id,
        &[json!({"n": 1}), json!({"n": 2}), json!({"n": 3})],
    )
    .await;

    let mut cfg = PubsubSourceConfig::new(sub_id);
    cfg.connection = PubsubConnection {
        project_id: Some(project),
        credentials: PubsubCredentials::Anonymous,
        ..Default::default()
    };
    cfg.value_format = ValueFormat::Json;
    cfg.idle_termination_secs = Some(3);
    cfg.max_messages = Some(3);

    let source = PubsubSource::new(cfg).await.expect("source builds");
    let records = source.fetch_all().await.expect("drain");
    assert_eq!(records.len(), 3, "all published messages delivered");
    assert!(records.iter().all(|r| r["data"]["n"].is_number()));
    assert!(records.iter().all(|r| r["message_id"].is_string()));
}

