//! Integration tests for the ClickHouse sink.
//!
//! These require a live ClickHouse server. They are **skipped cleanly** unless
//! `FAUCET_TEST_CLICKHOUSE_URL` is set (e.g. to `http://localhost:8123`), so the
//! default `cargo test` run — and CI without Docker — never touches the network.
//!
//! ```bash
//! docker run -d --rm -p 8123:8123 clickhouse/clickhouse-server
//! FAUCET_TEST_CLICKHOUSE_URL=http://localhost:8123 \
//!   cargo test -p faucet-sink-clickhouse --test integration -- --nocapture
//! ```

use faucet_core::Sink as _;
use faucet_sink_clickhouse::{ClickHouseSink, ClickHouseSinkConfig};
use serde_json::json;

fn server_url() -> Option<String> {
    std::env::var("FAUCET_TEST_CLICKHOUSE_URL").ok().filter(|s| !s.is_empty())
}

/// Run a raw statement over the HTTP interface (used for DDL + read-back).
async fn exec(url: &str, sql: &str) -> String {
    let client = reqwest::Client::new();
    let resp = client
        .post(url)
        .query(&[("database", "default")])
        .body(sql.to_string())
        .send()
        .await
        .expect("request sent");
    assert!(
        resp.status().is_success(),
        "statement failed ({}): {sql}",
        resp.status()
    );
    resp.text().await.expect("body")
}

#[tokio::test]
async fn inserts_rows_via_json_each_row() {
    let Some(url) = server_url() else {
        eprintln!("skipping: FAUCET_TEST_CLICKHOUSE_URL not set");
        return;
    };

    let table = "faucet_sink_it";
    exec(&url, &format!("DROP TABLE IF EXISTS {table}")).await;
    exec(
        &url,
        &format!("CREATE TABLE {table} (id UInt64, name String) ENGINE = MergeTree ORDER BY id"),
    )
    .await;

    let sink = ClickHouseSink::new(ClickHouseSinkConfig::new(&url, table).with_batch_size(2))
        .expect("sink construction");

    let records = vec![
        json!({"id": 1, "name": "alice"}),
        json!({"id": 2, "name": "bob"}),
        json!({"id": 3, "name": "carol"}),
    ];
    let written = sink.write_batch(&records).await.expect("write ok");
    assert_eq!(written, 3);

    let count = exec(&url, &format!("SELECT count() FROM {table} FORMAT TabSeparated")).await;
    assert_eq!(count.trim(), "3", "expected 3 rows inserted");

    exec(&url, &format!("DROP TABLE IF EXISTS {table}")).await;
}

