//! Integration tests for the ClickHouse source.
//!
//! These require a live ClickHouse server. They are **skipped cleanly** unless
//! `FAUCET_TEST_CLICKHOUSE_URL` is set (e.g. to `http://localhost:8123`), so the
//! default `cargo test` run — and CI without Docker — never touches the network.
//!
//! To run them locally:
//!
//! ```bash
//! docker run -d --rm -p 8123:8123 clickhouse/clickhouse-server
//! FAUCET_TEST_CLICKHOUSE_URL=http://localhost:8123 \
//!   cargo test -p faucet-source-clickhouse --test integration -- --nocapture
//! ```

use faucet_core::Source as _;
use faucet_source_clickhouse::{ClickHouseSource, ClickHouseSourceConfig};
use futures::StreamExt as _;

/// Returns the configured server URL, or `None` (test skipped) when the env var
/// is absent.
fn server_url() -> Option<String> {
    std::env::var("FAUCET_TEST_CLICKHOUSE_URL").ok().filter(|s| !s.is_empty())
}

#[tokio::test]
async fn streams_rows_from_system_numbers() {
    let Some(url) = server_url() else {
        eprintln!("skipping: FAUCET_TEST_CLICKHOUSE_URL not set");
        return;
    };

    // `system.numbers` needs no DDL and returns deterministic rows, so this
    // exercises the full streaming + JSONEachRow decode path with no setup.
    let cfg = ClickHouseSourceConfig::new(url, "SELECT number FROM system.numbers LIMIT 5")
        .with_batch_size(2);
    let source = ClickHouseSource::new(cfg).expect("source construction");

    let ctx = std::collections::HashMap::new();
    let mut pages = source.stream_pages(&ctx, 2);

    let mut rows = Vec::new();
    while let Some(page) = pages.next().await {
        let page = page.expect("page ok");
        rows.extend(page.records);
    }

    assert_eq!(rows.len(), 5, "expected 5 rows, got {}", rows.len());
    assert_eq!(rows[0]["number"], 0);
    assert_eq!(rows[4]["number"], 4);
}

