    let source = ClickHouseSource::new(ClickHouseSourceConfig::new(url, "SELECT 1"))
        .expect("source construction");
    let ctx = faucet_core::check::CheckContext {
        timeout: std::time::Duration::from_secs(5),
    };
    let report = source.check(&ctx).await.expect("check ok");
    assert!(
        matches!(
            report.probes[0].status,
            faucet_core::check::ProbeStatus::Pass { .. }
        ),
        "connect probe should pass against a live server: {:?}",
        report.probes[0]
    );
}

