//! Live-cluster integration tests for the Amazon Redshift source.
//!
//! Amazon Redshift has **no local container image**, so these tests cannot run
//! in the ordinary Docker-backed integration matrix. They are `#[ignore]`d by
//! default and only run when a real cluster is provided via environment
//! variables — intended for a scheduled CI job with Redshift credentials, not
//! the per-PR run. Run locally with:
//!
//! ```sh
//! export REDSHIFT_HOST=my-cluster.abc123.us-east-1.redshift.amazonaws.com
//! export REDSHIFT_DATABASE=dev
//! export REDSHIFT_USER=admin
//! export REDSHIFT_PASSWORD=...
//! cargo test -p faucet-source-redshift --test integration -- --ignored
//! ```

use std::collections::HashMap;

use faucet_common_redshift::RedshiftConnection;
use faucet_core::Source;
use faucet_source_redshift::{RedshiftReplication, RedshiftSource, RedshiftSourceConfig};

/// Build a connection from `REDSHIFT_*` env vars, or `None` if unset.
fn env_connection() -> Option<RedshiftConnection> {
    let host = std::env::var("REDSHIFT_HOST").ok()?;
    let database = std::env::var("REDSHIFT_DATABASE").ok()?;
    let user = std::env::var("REDSHIFT_USER").ok()?;
    let password = std::env::var("REDSHIFT_PASSWORD").ok()?;
    let mut conn = RedshiftConnection::new(host, database, user, password);
    if let Ok(port) = std::env::var("REDSHIFT_PORT") {
        if let Ok(p) = port.parse() {
            conn.port = p;
        }
    }
    Some(conn)
}

#[tokio::test]
#[ignore = "requires a live Redshift cluster (set REDSHIFT_* env vars)"]
async fn select_literal_row_round_trips() {
    let Some(connection) = env_connection() else {
        eprintln!("REDSHIFT_* env vars unset; skipping");
        return;
    };
    let config = RedshiftSourceConfig {
        connection,
        query: "SELECT 1 AS n, 'hello'::varchar AS greeting".into(),
        params: Vec::new(),
        max_connections: 2,
        batch_size: 1000,
        replication: RedshiftReplication::Full,
        state_key: None,
    };
    let source = RedshiftSource::new(config).expect("source builds");

    let ctx = HashMap::new();
    let rows = source.fetch_with_context(&ctx).await.expect("query runs");
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0]["n"], serde_json::json!(1));
    assert_eq!(rows[0]["greeting"], serde_json::json!("hello"));
}

#[tokio::test]
#[ignore = "requires a live Redshift cluster (set REDSHIFT_* env vars)"]
async fn check_probe_passes_against_live_cluster() {
    let Some(connection) = env_connection() else {
        eprintln!("REDSHIFT_* env vars unset; skipping");
        return;
    };
    let config = RedshiftSourceConfig {
        connection,
        query: "SELECT 1".into(),
        params: Vec::new(),
        max_connections: 2,
        batch_size: 1000,
        replication: RedshiftReplication::Full,
        state_key: None,
    };
    let source = RedshiftSource::new(config).expect("source builds");
    let ctx = faucet_core::check::CheckContext {
        timeout: std::time::Duration::from_secs(10),
    };
    let report = source.check(&ctx).await.expect("check runs");
    assert!(
        report
            .probes
            .iter()
            .all(|p| matches!(p.status, faucet_core::check::ProbeStatus::Pass))
    );
}

