1	//! Integration tests for the Amazon Redshift source against a real database via
2	//! testcontainers.
3	//!
4	//! Amazon Redshift has **no local container image**, but it speaks the
5	//! **PostgreSQL wire protocol** and this source connects through `sqlx`'s
6	//! Postgres driver (via `faucet-common-redshift`). A stock Postgres container
7	//! therefore exercises the real read path end-to-end: row decoding
8	//! (`src/convert.rs`), the streaming/paging loop (`src/stream.rs`), and the
9	//! incremental-replication bookmark logic — everything short of Redshift-only
10	//! SQL surface, which the source never emits.
11	//!
12	//! The connection points at the container with TLS disabled (`tls: false` →
13	//! `sslmode=prefer`), so it negotiates plaintext against a Postgres image that
14	//! has no server certificate. These tests require Docker and are **not**
15	//! `#[ignore]`d — they auto-start their own container. A process-wide mutex
16	//! serializes the containers within this test binary.
17	
18	use std::collections::HashMap;
19	use std::sync::OnceLock;
20	
21	use faucet_core::Source;
22	use faucet_source_redshift::{
23	    RedshiftConnection, RedshiftReplication, RedshiftSource, RedshiftSourceConfig,
24	};
25	use futures::StreamExt;
26	use serde_json::{Value, json};
27	use testcontainers::{ContainerAsync, ImageExt, runners::AsyncRunner};
28	use testcontainers_modules::postgres::Postgres;
29	
30	/// Serialize container startup within this binary so the tests don't race on
31	/// Docker resources (each test still boots + tears down its own container).
32	fn serial() -> &'static tokio::sync::Mutex<()> {
33	    static SERIAL: OnceLock<tokio::sync::Mutex<()>> = OnceLock::new();
34	    SERIAL.get_or_init(|| tokio::sync::Mutex::new(()))
35	}
36	
37	/// Start a Postgres container; return the handle and its mapped host port. The
38	/// container stays alive while the returned handle is held.
39	async fn start_postgres() -> (ContainerAsync<Postgres>, u16) {
40	    let image = Postgres::default().with_tag("16-alpine");
41	    let container: ContainerAsync<Postgres> =
42	        image.start().await.expect("postgres container start");
43	    let port = container
44	        .get_host_port_ipv4(5432)
45	        .await
46	        .expect("postgres port");
47	    (container, port)
48	}
49	
50	/// A Redshift `Password` connection pointed at the plaintext test container
51	/// (Postgres image defaults: db `postgres`, user/password `postgres`).
52	fn redshift_conn(port: u16) -> RedshiftConnection {
53	    let mut conn = RedshiftConnection::new("127.0.0.1", "postgres", "postgres", "postgres");
54	    conn.port = port;
55	    // The Postgres test image serves no TLS certificate; `tls: false` maps to
56	    // `sslmode=prefer`, which falls back to a plaintext connection.
57	    conn.tls = false;
58	    conn
59	}
60	
61	/// Open a raw `sqlx` pool for seeding/verification.
62	async fn seed_pool(port: u16) -> sqlx::PgPool {
63	    let url = format!("REDACTED");
64	    sqlx::PgPool::connect(&url).await.expect("seed pool connect")
65	}
66	
67	fn full_config(port: u16, query: &str, batch_size: usize) -> RedshiftSourceConfig {
68	    RedshiftSourceConfig {
69	        connection: redshift_conn(port),
70	        query: query.into(),
71	        params: Vec::new(),
72	        max_connections: 2,
73	        batch_size,
74	        replication: RedshiftReplication::Full,
75	        state_key: None,
76	    }
77	}
78	
79	/// Drain a source into `(records, final_bookmark)`.
80	async fn drain(source: &RedshiftSource) -> (Vec<Value>, Option<Value>) {
81	    let ctx: HashMap<String, Value> = HashMap::new();
82	    let mut pages = source.stream_pages(&ctx, 0);
83	    let mut records = Vec::new();
84	    let mut bookmark = None;
85	    while let Some(page) = pages.next().await {
86	        let page = page.expect("page ok");
87	        records.extend(page.records);
88	        if page.bookmark.is_some() {
89	            bookmark = page.bookmark;
90	        }
91	    }
92	    (records, bookmark)
93	}
