95	/// Every branch of `pg_value_to_json` is exercised by selecting one row spanning
96	/// int / text / numeric / bool / null / timestamp columns, and the decoded JSON
97	/// is asserted field-by-field.
98	#[tokio::test(flavor = "multi_thread")]
99	async fn decodes_typed_rows_to_json() {
100	    let _guard = serial().lock().await;
101	    let (_container, port) = start_postgres().await;
102	    let pool = seed_pool(port).await;
103	    sqlx::query(
104	        "CREATE TABLE typed (\
105	            id BIGINT, name TEXT, amount NUMERIC(10,2), flag BOOLEAN, \
106	            note TEXT, ts TIMESTAMPTZ)",
107	    )
108	    .execute(&pool)
109	    .await
110	    .expect("create table");
111	    sqlx::query(
112	        "INSERT INTO typed VALUES \
113	            (1, 'alice', 12.34, true, NULL, '2024-01-02T03:04:05Z'), \
114	            (2, 'bob', 99.99, false, 'hi', '2024-06-07T08:09:10Z')",
115	    )
116	    .execute(&pool)
117	    .await
118	    .expect("insert");
119	    pool.close().await;
120	
121	    let source = RedshiftSource::new(full_config(
122	        port,
