1	//! Integration tests against a real Google Cloud Pub/Sub **emulator** started
2	//! automatically in Docker via testcontainers — no external infra, no env
3	//! gating, not `#[ignore]`d. Mirrors the DB testcontainer template
4	//! (`crates/source/mssql/tests/integration.rs`).
5	//!
6	//! Requires Docker (the `google/cloud-sdk:*-emulators` image). Run with:
7	//! `cargo test -p faucet-source-pubsub --test integration`.
8	//!
9	//! A single emulator container is shared across every test in this binary (via
10	//! a leaked `OnceCell`), so its mapped port is stable. `PUBSUB_EMULATOR_HOST`
11	//! is written exactly once, inside the guarded init — the SDK's
12	//! `ClientConfig::default()` (used both by the setup client here and by the
13	//! connector's `build_client`) reads that env var and switches to the emulator
14	//! environment (no auth). Each test uses distinct topic / subscription names so
15	//! they run concurrently against the one emulator without a serialization lock.
16	
17	use faucet_common_pubsub::PubsubMessage;
18	use faucet_core::{CheckContext, Source};
19	use faucet_source_pubsub::{
20	    PubsubConnection, PubsubCredentials, PubsubSource, PubsubSourceConfig, ValueFormat,
21	};
22	use gcloud_pubsub::client::{Client, ClientConfig};
23	use tokio::sync::OnceCell;
24	
25	use testcontainers_modules::google_cloud_sdk_emulators::{CloudSdk, PUBSUB_PORT};
26	use testcontainers_modules::testcontainers::runners::AsyncRunner;
27	
28	/// Every topic/subscription is created under this project id; the emulator
29	/// accepts any project name. The connector and the setup client must agree, or
30	/// they would address different `projects/<id>/…` namespaces.
31	const PROJECT: &str = "faucet-test";
32	
33	/// The shared emulator's `host:port` (127.0.0.1:<mapped 8085>).
34	static EMULATOR_HOST: OnceCell<String> = OnceCell::const_new();
35	
36	/// Start (once) the Pub/Sub emulator, publish its host into the process env,
37	/// and return `host:port`. The container is intentionally leaked so it lives
38	/// for the whole test binary.
39	async fn emulator_host() -> &'static str {
40	    EMULATOR_HOST
41	        .get_or_init(|| async {
42	            let container = CloudSdk::pubsub()
43	                .start()
44	                .await
45	                .expect("start pubsub emulator container");
46	            let port = container
47	                .get_host_port_ipv4(PUBSUB_PORT)
48	                .await
49	                .expect("pubsub emulator host port");
50	            let host = format!("127.0.0.1:{port}");
51	            // SAFETY: this write happens exactly once — `get_or_init` serializes
52	            // concurrent callers, and no other code reads the env var until
53	            // after this future has completed.
54	            unsafe {
55	                std::env::set_var("PUBSUB_EMULATOR_HOST", &host);
56	            }
57	            // Keep the container alive for the process lifetime.
58	            Box::leak(Box::new(container));
59	            host
60	        })
61	        .await
62	        .as_str()
63	}
64	
65	/// A setup/admin client pointed at the emulator, scoped to `PROJECT`.
66	async fn setup_client() -> Client {
67	    let mut config = ClientConfig::default(); // reads PUBSUB_EMULATOR_HOST
68	    config.project_id = Some(PROJECT.to_string());
69	    Client::new(config).await.expect("emulator setup client")
70	}
71	
72	fn conn(host: &str) -> PubsubConnection {
73	    PubsubConnection {
74	        project_id: Some(PROJECT.into()),
75	        emulator_host: Some(host.to_string()),
76	        credentials: PubsubCredentials::Anonymous,
77	        ..Default::default()
78	    }
79	}
80	
81	async fn create_topic_sub(client: &Client, topic_id: &str, sub_id: &str) {
82	    let topic = client
83	        .create_topic(topic_id, None, None)
84	        .await
85	        .expect("create topic");
86	    client
87	        .create_subscription(sub_id, topic.fully_qualified_name(), Default::default(), None)
88	        .await
89	        .expect("create subscription");
90	}
91	
92	fn msg(data: &[u8], attrs: &[(&str, &str)], ordering_key: &str) -> PubsubMessage {
93	    PubsubMessage {
94	        data: data.to_vec(),
95	        attributes: attrs
96	            .iter()
97	            .map(|(k, v)| ((*k).to_string(), (*v).to_string()))
98	            .collect(),
99	        ordering_key: ordering_key.to_string(),
100	        ..Default::default()
101	    }
102	}
103	
104	async fn publish(client: &Client, topic_id: &str, messages: Vec<PubsubMessage>) {
105	    let topic = client.topic(topic_id);
106	    let publisher = topic.new_publisher(None);
107	    let mut awaiters = Vec::with_capacity(messages.len());
108	    for m in messages {
109	        awaiters.push(publisher.publish(m).await);
110	    }
111	    for a in awaiters {
112	        a.get().await.expect("publish message");
113	    }
114	}
115	
116	/// JSON value_format: attributes surfaced under `__attributes`, `message_id` /
117	/// `publish_time_millis` populated by the server, an ordering key round-tripped,
118	/// multi-page draining (`batch_size = 2` over 3 messages), and the `check()`
119	/// subscription-exists probe. Exercises `stream.rs` streaming-pull + ack path
120	/// and `convert.rs` JSON decoding + attribute mapping.
121	#[tokio::test(flavor = "multi_thread")]
122	async fn source_json_multipage_attributes_and_check() {
123	    let host = emulator_host().await;
124	    let client = setup_client().await;
125	    create_topic_sub(&client, "src-json-t", "src-json-s").await;
126	    publish(
127	        &client,
128	        "src-json-t",
129	        vec![
130	            msg(br#"{"n":1}"#, &[("origin", "eu")], "ok-1"),
131	            msg(br#"{"n":2}"#, &[], ""),
132	            msg(br#"{"n":3}"#, &[], ""),
133	        ],
134	    )
135	    .await;
136	
137	    let mut cfg = PubsubSourceConfig::new("src-json-s");
138	    cfg.connection = conn(host);
139	    cfg.value_format = ValueFormat::Json;
140	    cfg.idle_termination_secs = Some(5);
141	    cfg.max_messages = Some(3);
142	    cfg.batch_size = 2; // 3 messages → pages of 2 + 1: exercises ack-at-page-boundary
143	    let source = PubsubSource::new(cfg).await.expect("source builds");
144	
145	    // Side-effect-free preflight probe (subscription exists).
146	    let report = source
147	        .check(&CheckContext::default())
148	        .await
149	        .expect("check runs");
150	    assert_eq!(report.failed_count(), 0, "subscription-exists probe passes");
151	
152	    let mut records = source.fetch_all().await.expect("drain");
153	    assert_eq!(records.len(), 3, "all published messages delivered");
154	    records.sort_by_key(|r| r["data"]["n"].as_i64().unwrap());
155	    assert_eq!(records[0]["data"]["n"], 1);
156	    assert_eq!(records[2]["data"]["n"], 3);
157	    assert!(
158	        records.iter().all(|r| r["message_id"].is_string()),
159	        "server-assigned message_id present"
160	    );
161	    assert!(
162	        records.iter().all(|r| r["publish_time_millis"].is_i64()),
163	        "server-assigned publish_time_millis present: {records:?}"
164	    );
165	    // Attribute map surfaced under the default `__attributes` key.
166	    assert!(
167	        records
168	            .iter()
169	            .any(|r| r["__attributes"]["origin"] == "eu"),
170	        "attribute mapping: {records:?}"
171	    );
172	    // Ordering key round-tripped onto the record.
173	    assert!(
174	        records.iter().any(|r| r["ordering_key"] == "ok-1"),
175	        "ordering key surfaced: {records:?}"
176	    );
177	}
178	
179	/// `value_format: string` decodes the raw payload as UTF-8.
180	#[tokio::test(flavor = "multi_thread")]
181	async fn source_value_format_string() {
182	    let host = emulator_host().await;
183	    let client = setup_client().await;
184	    create_topic_sub(&client, "src-str-t", "src-str-s").await;
185	    publish(
186	        &client,
187	        "src-str-t",
188	        vec![msg(b"hello world", &[], ""), msg("h\u{e9}llo".as_bytes(), &[], "")],
189	    )
190	    .await;
191	
192	    let mut cfg = PubsubSourceConfig::new("src-str-s");
193	    cfg.connection = conn(host);

