159	#[cfg(test)]
160	mod tests {
161	    use super::*;
162	
163	    #[test]
164	    fn debug_masks_password() {
165	        let c = RedshiftCredentials::Password {
166	            password: "s3cr3t".into(),
167	        };
168	        let dbg = format!("{c:?}");
169	        assert!(dbg.contains("***"));
170	        assert!(!dbg.contains("s3cr3t"));
171	    }
