1	//! Integration tests for `faucet-sink-azure-blob` against an auto-started
2	//! Azurite emulator (via `testcontainers-modules`).
3	//!
4	//! These boot a real Azurite container, create a destination blob container,
5	//! drive the connector's real write path (`write_batch` + `flush`), then read
6	//! the written objects back through an `object_store` Azure client and assert
7	//! the JSONL bodies. They are **not** `#[ignore]`d and **not** env-gated — CI's
8	//! `--all-features` test/coverage jobs run them with Docker present, which is
9	//! what exercises the serialize / key-generation / upload / rollover lines in
10	//! `src/sink.rs`.
11	//!
12	//! Container creation goes through the Azure SDK (`object_store` cannot create a
13	//! container); every other blob operation goes through `object_store`.
14	
15	#![cfg(not(target_os = "windows"))]
16	
17	use std::sync::Arc;
18	
19	use faucet_core::Sink;
20	use faucet_sink_azure_blob::{AzureBlobSink, AzureBlobSinkConfig, AzureCredentials};
21	use futures::StreamExt;
22	use object_store::azure::MicrosoftAzureBuilder;
23	use object_store::path::Path as ObjPath;
24	use object_store::{ObjectStore, ObjectStoreExt};
25	use serde_json::{Value, json};
26	use testcontainers_modules::azurite::{Azurite, BLOB_PORT};
27	use testcontainers_modules::testcontainers::ContainerAsync;
28	use testcontainers_modules::testcontainers::runners::AsyncRunner;
29	
30	/// Well-known Azurite dev account + key (`devstoreaccount1`).
31	const AZURITE_ACCOUNT: &str = "devstoreaccount1";
32	const AZURITE_KEY: &str =
33	    "REDACTED/K1SZFPTOtr/KBHBeksoGMGw==";
34	const CONTAINER: &str = "faucet-test";
35	
36	// Azurite is lightweight, but `cargo test` runs a binary's tests concurrently;
37	// serialize so at most one emulator container runs at a time (steadier on CI).
38	static SERIAL: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());
39	
40	/// Start Azurite; return the container handle plus its mapped blob port. The
41	/// handle must be held for the duration of the test to keep the container up.
42	async fn start_azurite() -> (ContainerAsync<Azurite>, u16) {
43	    let container = Azurite::default()
44	        .start()
45	        .await
46	        .expect("start azurite container");
47	    let port = container
48	        .get_host_port_ipv4(BLOB_PORT)
49	        .await
50	        .expect("azurite blob host port");
51	    (container, port)
52	}
53	
54	fn endpoint(port: u16) -> String {
55	    format!("http://127.0.0.1:{port}/{AZURITE_ACCOUNT}")
56	}
57	
58	/// Create the destination blob container via the Azure SDK (`object_store` has
59	/// no container-management API).
60	async fn create_container(port: u16) {
61	    use azure_storage::{CloudLocation, prelude::*};
62	    use azure_storage_blobs::prelude::*;
63	
64	    ClientBuilder::with_location(
65	        CloudLocation::Emulator {
66	            address: "127.0.0.1".to_owned(),
67	            port,
68	        },
69	        StorageCredentials::emulator(),
70	    )
71	    .container_client(CONTAINER)
72	    .create()
73	    .await
74	    .expect("create azurite blob container");
75	}
76	
77	/// Build an `object_store` Azure client for reading the written objects back.
78	fn verify_store(port: u16) -> Arc<dyn ObjectStore> {
79	    Arc::new(
80	        MicrosoftAzureBuilder::new()
81	            .with_account(AZURITE_ACCOUNT)
82	            .with_access_key(AZURITE_KEY)
83	            .with_container_name(CONTAINER)
84	            .with_endpoint(endpoint(port))
85	            .with_allow_http(true)
86	            .build()
87	            .expect("build verifying object store"),
88	    )
89	}
90	
91	/// List every object key under `prefix`, sorted (UUIDv7 keys sort by write order).
92	async fn list_keys(store: &Arc<dyn ObjectStore>, prefix: &str) -> Vec<String> {
93	    let mut listing = store.list(Some(&ObjPath::from(prefix)));
94	    let mut keys = Vec::new();
95	    while let Some(meta) = listing.next().await {
96	        keys.push(meta.expect("list meta").location.to_string());
97	    }
98	    keys.sort();
99	    keys
100	}
101	
102	/// Download an object body and parse it as JSON Lines records.
103	async fn read_jsonl(store: &Arc<dyn ObjectStore>, key: &str) -> Vec<Value> {
104	    let bytes = store
105	        .get(&ObjPath::from(key))
106	        .await
107	        .expect("get object")
108	        .bytes()
109	        .await
110	        .expect("read object bytes");
111	    let text = String::from_utf8(bytes.to_vec()).expect("utf8 body");
112	    text.lines()
113	        .filter(|l| !l.trim().is_empty())
114	        .map(|l| serde_json::from_str::<Value>(l).expect("parse jsonl line"))
115	        .collect()
116	}
117	
118	fn sink_config(port: u16) -> AzureBlobSinkConfig {
119	    AzureBlobSinkConfig::new(CONTAINER)
120	        .account(AZURITE_ACCOUNT)
121	        .auth(AzureCredentials::AccountKey {
122	            account_key: AZURITE_KEY.into(),
123	        })
124	        .endpoint(endpoint(port))
125	        .allow_http(true)
126	}
