128	// ── Happy path: write a batch as one object and read the rows back ───────────
129	
130	#[tokio::test(flavor = "multi_thread")]
131	async fn sink_writes_and_reads_back() {
132	    let _serial = SERIAL.lock().await;
133	    let (_c, port) = start_azurite().await;
134	    create_container(port).await;
135	
136	    // batch_size = 0 → the whole page is written as a single object.
137	    let sink = AzureBlobSink::new(sink_config(port).prefix("out/").with_batch_size(0))
138	        .await
139	        .expect("sink new");
140	
141	    let records = vec![json!({"id": 1}), json!({"id": 2}), json!({"id": 3})];
142	    let written = sink.write_batch(&records).await.expect("write_batch");
143	    assert_eq!(written, 3);
144	    sink.flush().await.expect("flush");
145	
146	    let store = verify_store(port);
147	    let keys = list_keys(&store, "out").await;
148	    assert_eq!(keys.len(), 1, "batch_size=0 writes a single object");
149	    assert!(keys[0].starts_with("out/") && keys[0].ends_with(".jsonl"));
150	
151	    let rows = read_jsonl(&store, &keys[0]).await;
152	    let mut ids: Vec<i64> = rows.iter().map(|r| r["id"].as_i64().unwrap()).collect();
153	    ids.sort_unstable();
154	    assert_eq!(ids, vec![1, 2, 3]);
155	}
156	
157	// ── Rollover: max_records_per_file splits a batch across multiple objects ────
158	
159	#[tokio::test(flavor = "multi_thread")]
160	async fn sink_rolls_over_multiple_files() {
161	    let _serial = SERIAL.lock().await;
162	    let (_c, port) = start_azurite().await;
163	    create_container(port).await;
164	
165	    let sink = AzureBlobSink::new(
166	        sink_config(port)
167	            .prefix("roll/")
168	            .with_batch_size(0)
169	            .max_records_per_file(2)
170	            .concurrency(4),
171	    )
172	    .await
173	    .expect("sink new");
174	
175	    let records: Vec<Value> = (1..=5).map(|i| json!({ "id": i })).collect();
176	    let written = sink.write_batch(&records).await.expect("write_batch");
177	    assert_eq!(written, 5);
178	
179	    let store = verify_store(port);
180	    let keys = list_keys(&store, "roll").await;
181	    assert_eq!(keys.len(), 3, "5 records at 2/file → 3 objects");
182	
183	    // Every record must land exactly once across the rolled-over objects.
184	    let mut all_ids = Vec::new();
185	    for key in &keys {
186	        for row in read_jsonl(&store, key).await {
187	            all_ids.push(row["id"].as_i64().unwrap());
188	        }
189	    }
190	    all_ids.sort_unstable();
191	    assert_eq!(all_ids, vec![1, 2, 3, 4, 5]);
192	}
193	
194	// ── Empty batch is a no-op (no object written) ───────────────────────────────
195	
196	#[tokio::test(flavor = "multi_thread")]
197	async fn sink_write_batch_empty_is_noop() {
